CREATE TABLE public.org_people(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE,name text NOT NULL,email text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'invited' CHECK(status IN ('invited','active','deactivated')),last_active timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.org_people TO authenticated; GRANT ALL ON public.org_people TO service_role; ALTER TABLE public.org_people ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_person_roles(person_id uuid NOT NULL REFERENCES public.org_people(id),role text NOT NULL CHECK(role IN ('admin','hr','hiring_manager','analyst','sme','rater')),PRIMARY KEY(person_id,role));
GRANT SELECT,INSERT,DELETE ON public.org_person_roles TO authenticated; GRANT ALL ON public.org_person_roles TO service_role; ALTER TABLE public.org_person_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),person_id uuid NOT NULL REFERENCES public.org_people(id),role_id uuid NOT NULL,permission text NOT NULL CHECK(permission IN ('hiring_manager','sme','rater')),source_id text NOT NULL DEFAULT '',UNIQUE(person_id,role_id,permission));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.org_assignments TO authenticated;GRANT ALL ON public.org_assignments TO service_role;ALTER TABLE public.org_assignments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),name text NOT NULL DEFAULT 'People at Work',logo_path text NOT NULL DEFAULT '',onet_mode text NOT NULL DEFAULT 'demo' CHECK(onet_mode IN ('demo','live')),candidate_days integer NOT NULL DEFAULT 30 CHECK(candidate_days BETWEEN 1 AND 365),retention_months integer NOT NULL DEFAULT 12 CHECK(retention_months BETWEEN 1 AND 120),privacy_notice text NOT NULL DEFAULT 'Your responses are used to assess job-relevant skills and are reviewed by authorized members of the hiring team. Optional demographic information is kept separate from scoring. Candidate data is retained for 12 months. Contact the hiring team with privacy or accommodation questions.');
GRANT SELECT,INSERT,UPDATE ON public.org_settings TO authenticated; GRANT ALL ON public.org_settings TO service_role; ALTER TABLE public.org_settings ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),person_id uuid NOT NULL REFERENCES public.org_people(id),expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',revoked boolean NOT NULL DEFAULT false,accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.org_invitations TO authenticated;GRANT ALL ON public.org_invitations TO service_role;ALTER TABLE public.org_invitations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.assessment_campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),battery_id uuid NOT NULL REFERENCES public.assessment_batteries(id),name text NOT NULL,created_by uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.assessment_campaigns TO authenticated;GRANT ALL ON public.assessment_campaigns TO service_role;ALTER TABLE public.assessment_campaigns ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.assessment_rater_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid NOT NULL REFERENCES public.assessment_attempts(id),item_id text NOT NULL,person_id uuid NOT NULL REFERENCES public.org_people(id),UNIQUE(attempt_id,item_id,person_id));
GRANT SELECT,INSERT,DELETE ON public.assessment_rater_assignments TO authenticated;GRANT ALL ON public.assessment_rater_assignments TO service_role;ALTER TABLE public.assessment_rater_assignments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.hiring_decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid NOT NULL REFERENCES public.assessment_attempts(id),decision text NOT NULL CHECK(decision IN ('hire','hold','decline')),note text NOT NULL,decided_by uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.hiring_decisions TO authenticated;GRANT ALL ON public.hiring_decisions TO service_role;ALTER TABLE public.hiring_decisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.assessment_attempts ADD COLUMN campaign_id uuid REFERENCES public.assessment_campaigns(id), ADD COLUMN privacy_notice text NOT NULL DEFAULT '', ADD COLUMN privacy_accepted_at timestamptz, ADD COLUMN purged_at timestamptz;
CREATE FUNCTION public.org_active(uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM org_people WHERE user_id=uid) THEN EXISTS(SELECT 1 FROM org_people WHERE user_id=uid AND status='active') ELSE EXISTS(SELECT 1 FROM user_roles WHERE user_id=uid) END $$;
CREATE FUNCTION public.org_has_role(uid uuid,r text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT org_active(uid) AND (EXISTS(SELECT 1 FROM org_people p JOIN org_person_roles pr ON pr.person_id=p.id WHERE p.user_id=uid AND pr.role=r) OR EXISTS(SELECT 1 FROM user_roles ur WHERE ur.user_id=uid AND ur.role::text=CASE r WHEN 'hr' THEN 'hr_reviewer' ELSE r END)) $$;
CREATE OR REPLACE FUNCTION public.has_role(user_id uuid,role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT org_has_role($1,CASE $2::text WHEN 'hr_reviewer' THEN 'hr' ELSE $2::text END) OR ($2::text='hr_reviewer' AND org_has_role($1,'admin')) $$;
CREATE FUNCTION public.org_assigned(uid uuid,rid uuid,p text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT org_has_role(uid,'admin') OR (org_has_role(uid,p) AND EXISTS(SELECT 1 FROM org_assignments a JOIN org_people u ON u.id=a.person_id WHERE u.user_id=uid AND a.role_id=rid AND a.permission=p)) $$;
CREATE FUNCTION public.org_can(cap text,rid uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT org_has_role(auth.uid(),'admin') OR CASE cap WHEN 'people' THEN false WHEN 'campaigns' THEN org_has_role(auth.uid(),'hr') WHEN 'approve' THEN org_has_role(auth.uid(),'hr') WHEN 'results' THEN org_has_role(auth.uid(),'hr') OR org_assigned(auth.uid(),rid,'hiring_manager') WHEN 'decision' THEN org_assigned(auth.uid(),rid,'hiring_manager') WHEN 'analysis' THEN org_has_role(auth.uid(),'analyst') WHEN 'fairness' THEN org_has_role(auth.uid(),'analyst') WHEN 'sme' THEN org_assigned(auth.uid(),rid,'sme') WHEN 'score' THEN org_assigned(auth.uid(),rid,'rater') ELSE false END $$;
CREATE OR REPLACE FUNCTION public.assessment_permission(bid uuid,p text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT org_assigned(auth.uid(),bid,p) OR (org_has_role(auth.uid(),'admin')) $$;
REVOKE ALL ON FUNCTION public.org_active(uuid),public.org_has_role(uuid,text),public.org_assigned(uuid,uuid,text),public.org_can(text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.org_active(uuid),public.org_has_role(uuid,text),public.org_assigned(uuid,uuid,text),public.org_can(text,uuid) TO authenticated,service_role;
CREATE POLICY people_read ON org_people FOR SELECT TO authenticated USING(org_can('people') OR user_id=auth.uid());CREATE POLICY people_write ON org_people FOR ALL TO authenticated USING(org_can('people')) WITH CHECK(org_can('people'));
CREATE POLICY roles_read ON org_person_roles FOR SELECT TO authenticated USING(org_can('people') OR person_id IN(SELECT id FROM org_people WHERE user_id=auth.uid()));CREATE POLICY roles_write ON org_person_roles FOR ALL TO authenticated USING(org_can('people')) WITH CHECK(org_can('people'));
CREATE POLICY assignments_read ON org_assignments FOR SELECT TO authenticated USING(org_can('people') OR person_id IN(SELECT id FROM org_people WHERE user_id=auth.uid()));CREATE POLICY assignments_write ON org_assignments FOR ALL TO authenticated USING(org_can('people')) WITH CHECK(org_can('people'));
CREATE POLICY settings_read ON org_settings FOR SELECT TO authenticated USING(org_active(auth.uid()));CREATE POLICY settings_write ON org_settings FOR ALL TO authenticated USING(org_can('people')) WITH CHECK(org_can('people'));
CREATE POLICY invitations_admin ON org_invitations FOR ALL TO authenticated USING(org_can('people')) WITH CHECK(org_can('people'));
CREATE POLICY campaigns_read ON assessment_campaigns FOR SELECT TO authenticated USING(org_can('results',battery_id));CREATE POLICY campaigns_insert ON assessment_campaigns FOR INSERT TO authenticated WITH CHECK(org_can('campaigns',battery_id));
CREATE POLICY rater_assign_read ON assessment_rater_assignments FOR SELECT TO authenticated USING(org_can('people') OR person_id IN(SELECT id FROM org_people WHERE user_id=auth.uid()));CREATE POLICY rater_assign_write ON assessment_rater_assignments FOR ALL TO authenticated USING(org_can('people')) WITH CHECK(org_can('people'));
CREATE POLICY decisions_read ON hiring_decisions FOR SELECT TO authenticated USING(org_can('results',(SELECT battery_id FROM assessment_attempts WHERE id=attempt_id)));CREATE POLICY decisions_insert ON hiring_decisions FOR INSERT TO authenticated WITH CHECK(decided_by=auth.uid() AND org_can('decision',(SELECT battery_id FROM assessment_attempts WHERE id=attempt_id)));
DROP POLICY attempt_read ON assessment_attempts;DROP POLICY attempt_insert ON assessment_attempts;DROP POLICY attempt_update ON assessment_attempts;
CREATE POLICY attempt_read ON assessment_attempts FOR SELECT TO authenticated USING(org_can('results',battery_id));CREATE POLICY attempt_insert ON assessment_attempts FOR INSERT TO authenticated WITH CHECK(org_can('campaigns',battery_id));
DROP POLICY battery_read ON assessment_batteries;CREATE POLICY battery_read ON assessment_batteries FOR SELECT TO authenticated USING(org_can('analysis',id) OR org_can('approve',id) OR org_can('results',id) OR org_can('sme',id));
DROP POLICY demographic_review ON assessment_demographics;CREATE POLICY demographic_review ON assessment_demographics FOR SELECT TO authenticated USING(org_can('fairness'));
CREATE FUNCTION public.org_guard_person() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(991112026);IF TG_OP='DELETE' THEN RAISE EXCEPTION 'People cannot be deleted';END IF;IF TG_OP='UPDATE' THEN IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.email IS DISTINCT FROM OLD.email THEN IF coalesce(auth.role(),'')<>'service_role' AND auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'Account identity cannot be changed';END IF;END IF;IF OLD.status='active' AND NEW.status<>'active' AND EXISTS(SELECT 1 FROM org_person_roles WHERE person_id=OLD.id AND role='admin') AND NOT EXISTS(SELECT 1 FROM org_person_roles pr JOIN org_people p ON p.id=pr.person_id WHERE pr.role='admin' AND p.status='active' AND p.id<>OLD.id) THEN RAISE EXCEPTION 'Keep at least one active Admin';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER org_person_guard BEFORE UPDATE OR DELETE ON org_people FOR EACH ROW EXECUTE FUNCTION org_guard_person();
CREATE FUNCTION public.org_guard_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(991112026);IF TG_OP='DELETE' THEN IF OLD.role='admin' AND EXISTS(SELECT 1 FROM org_people WHERE id=OLD.person_id AND status='active') AND NOT EXISTS(SELECT 1 FROM org_people p JOIN org_person_roles r ON r.person_id=p.id WHERE r.role='admin' AND p.status='active' AND p.id<>OLD.person_id) THEN RAISE EXCEPTION 'Keep at least one active Admin';END IF;RETURN OLD;END IF;RETURN NEW;END $$;
CREATE TRIGGER org_role_guard BEFORE INSERT OR DELETE ON org_person_roles FOR EACH ROW EXECUTE FUNCTION org_guard_role();
CREATE FUNCTION public.org_guard_assignment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM org_people p JOIN org_person_roles r ON r.person_id=p.id WHERE p.id=NEW.person_id AND p.status='active' AND r.role=NEW.permission) THEN RAISE EXCEPTION 'Assignment requires matching active organization role';END IF;RETURN NEW;END $$;
CREATE TRIGGER org_assignment_guard BEFORE INSERT OR UPDATE ON org_assignments FOR EACH ROW EXECUTE FUNCTION org_guard_assignment();
CREATE FUNCTION public.org_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v jsonb;oldv jsonb;eid uuid;BEGIN v:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;oldv:=CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE '{}'::jsonb END; eid:=coalesce((v->>'id')::uuid,(v->>'person_id')::uuid);INSERT INTO activity_log(user_id,action,entity_type,entity_id,details) VALUES(auth.uid(),TG_OP,TG_TABLE_NAME,eid,jsonb_build_object('before',oldv-ARRAY['email','privacy_notice'],'after',v-ARRAY['email','privacy_notice']));RETURN coalesce(NEW,OLD);END $$;
CREATE TRIGGER audit_people AFTER INSERT OR UPDATE ON org_people FOR EACH ROW EXECUTE FUNCTION org_audit();CREATE TRIGGER audit_person_roles AFTER INSERT OR DELETE ON org_person_roles FOR EACH ROW EXECUTE FUNCTION org_audit();CREATE TRIGGER audit_org_assignments AFTER INSERT OR UPDATE OR DELETE ON org_assignments FOR EACH ROW EXECUTE FUNCTION org_audit();CREATE TRIGGER audit_invitations AFTER INSERT OR UPDATE ON org_invitations FOR EACH ROW EXECUTE FUNCTION org_audit();CREATE TRIGGER audit_campaigns AFTER INSERT ON assessment_campaigns FOR EACH ROW EXECUTE FUNCTION org_audit();CREATE TRIGGER audit_decisions AFTER INSERT ON hiring_decisions FOR EACH ROW EXECUTE FUNCTION org_audit();CREATE TRIGGER audit_rater_assignments AFTER INSERT OR DELETE ON assessment_rater_assignments FOR EACH ROW EXECUTE FUNCTION org_audit();
CREATE FUNCTION public.org_save_person(v jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid; rr text;BEGIN PERFORM pg_advisory_xact_lock(991112026);IF NOT org_can('people') THEN RAISE EXCEPTION 'Admin access required';END IF;IF jsonb_array_length(v->'roles')=0 THEN RAISE EXCEPTION 'Choose at least one role';END IF;IF v->>'id' IS NULL THEN INSERT INTO org_people(name,email) VALUES(v->>'name',lower(v->>'email')) RETURNING id INTO pid;ELSE pid:=(v->>'id')::uuid;UPDATE org_people SET name=v->>'name',status=v->>'status' WHERE id=pid;IF NOT FOUND THEN RAISE EXCEPTION 'Person not found';END IF;END IF;FOR rr IN SELECT jsonb_array_elements_text(v->'roles') LOOP INSERT INTO org_person_roles(person_id,role) VALUES(pid,rr) ON CONFLICT DO NOTHING;END LOOP;DELETE FROM org_person_roles WHERE person_id=pid AND NOT (v->'roles' ? role);RETURN pid;END $$;
REVOKE ALL ON FUNCTION org_save_person(jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION org_save_person(jsonb) TO authenticated;
CREATE FUNCTION public.org_guard_sme() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid text;BEGIN IF auth.uid() IS NULL OR coalesce(auth.role(),'')='service_role' OR org_can('analysis',NEW.id) OR org_can('approve',NEW.id) THEN RETURN NEW;END IF;IF TG_OP='UPDATE' THEN IF NOT org_can('sme',NEW.id) THEN RAISE EXCEPTION 'Assigned SME required';END IF;SELECT a.source_id INTO sid FROM org_assignments a JOIN org_people p ON p.id=a.person_id WHERE a.role_id=NEW.id AND a.permission='sme' AND p.user_id=auth.uid();IF (NEW.payload-ARRAY['ratings','incidents']) IS DISTINCT FROM (OLD.payload-ARRAY['ratings','incidents']) THEN RAISE EXCEPTION 'SME may edit only ratings and incidents';END IF;IF (SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') FROM jsonb_array_elements(NEW.payload->'ratings') WHERE value->>'source_id'<>sid) IS DISTINCT FROM (SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') FROM jsonb_array_elements(OLD.payload->'ratings') WHERE value->>'source_id'<>sid) OR (SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') FROM jsonb_array_elements(NEW.payload->'incidents') WHERE value->>'source_id'<>sid) IS DISTINCT FROM (SELECT coalesce(jsonb_agg(value ORDER BY value::text),'[]') FROM jsonb_array_elements(OLD.payload->'incidents') WHERE value->>'source_id'<>sid) THEN RAISE EXCEPTION 'Other SME judgments immutable';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER org_sme_guard BEFORE UPDATE ON assessment_batteries FOR EACH ROW EXECUTE FUNCTION org_guard_sme();
CREATE POLICY logo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='organization-logos' AND org_active(auth.uid()));CREATE POLICY logo_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='organization-logos' AND org_can('people'));CREATE POLICY logo_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='organization-logos' AND org_can('people')) WITH CHECK(bucket_id='organization-logos' AND org_can('people'));
COMMENT ON TABLE assessment_access IS 'DEPRECATED: org_assignments provides active organization-role-bound access; retained for historical records.';